CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, password TEXT NOT NULL, admin_role TEXT CHECK(admin_role IN ('support','admin')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE tenants (id TEXT PRIMARY KEY, name TEXT NOT NULL, plan_id TEXT NOT NULL DEFAULT 'starter', billing_state TEXT NOT NULL DEFAULT 'free');
CREATE TABLE memberships (user_id TEXT REFERENCES users(id) ON DELETE CASCADE, tenant_id TEXT REFERENCES tenants(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK(role IN ('owner','manager','staff')), PRIMARY KEY(user_id,tenant_id));
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL);
CREATE TABLE plans (id TEXT PRIMARY KEY, name TEXT NOT NULL, entitlements TEXT NOT NULL, price_paise INTEGER);
INSERT INTO plans VALUES ('starter','Starter','{"locations":1,"staff":0,"orders":true,"analytics":true,"modules":true}',0),('prime','Prime','{"locations":10,"staff":20,"orders":true,"analytics":true,"modules":true}',NULL);
CREATE TABLE locations (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, category TEXT NOT NULL, profile TEXT NOT NULL, published INTEGER NOT NULL DEFAULT 0, active_route_id TEXT, previous_route_id TEXT, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE items (id TEXT PRIMARY KEY, location_id TEXT NOT NULL REFERENCES locations(id) ON DELETE CASCADE, name TEXT NOT NULL, description TEXT NOT NULL, section TEXT NOT NULL, price_paise INTEGER NOT NULL CHECK(price_paise>=0), available INTEGER NOT NULL DEFAULT 1, image TEXT);
CREATE TABLE routes (id TEXT PRIMARY KEY, location_id TEXT NOT NULL REFERENCES locations(id) ON DELETE CASCADE, label TEXT NOT NULL, provider TEXT NOT NULL, vpa TEXT NOT NULL, payee TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('draft','verification_pending','verified','active','disabled','failed')), evidence TEXT, verified_by TEXT, verified_at TEXT);
CREATE TABLE orders (id TEXT PRIMARY KEY, location_id TEXT NOT NULL REFERENCES locations(id) ON DELETE CASCADE, idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, access_token TEXT NOT NULL, state TEXT NOT NULL, payment_state TEXT NOT NULL DEFAULT 'pending', amount_paise INTEGER NOT NULL, lines TEXT NOT NULL, instructions TEXT NOT NULL, order_type TEXT NOT NULL, payment_method TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(location_id,idempotency_key));
CREATE TABLE attempts (id TEXT PRIMARY KEY, location_id TEXT NOT NULL REFERENCES locations(id) ON DELETE CASCADE, order_id TEXT REFERENCES orders(id) ON DELETE CASCADE, idempotency_key TEXT NOT NULL, route_id TEXT NOT NULL, snapshot TEXT NOT NULL, amount_paise INTEGER, state TEXT NOT NULL DEFAULT 'confirmation_pending', provider_reference TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(location_id,idempotency_key));
CREATE TABLE requests (id TEXT PRIMARY KEY, location_id TEXT NOT NULL REFERENCES locations(id) ON DELETE CASCADE, name TEXT NOT NULL, contact TEXT NOT NULL, message TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'new', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit (id TEXT PRIMARY KEY, tenant_id TEXT, actor_id TEXT NOT NULL, action TEXT NOT NULL, record_id TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER audit_no_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT,'audit immutable'); END;
CREATE TRIGGER audit_no_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT,'audit immutable'); END;
CREATE TABLE events (location_id TEXT NOT NULL REFERENCES locations(id) ON DELETE CASCADE, day TEXT NOT NULL, kind TEXT NOT NULL, count INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(location_id,day,kind));
CREATE TABLE push_tokens (token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE outbox (id TEXT PRIMARY KEY, location_id TEXT NOT NULL REFERENCES locations(id) ON DELETE CASCADE, title TEXT NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, delivered_at TEXT, tries INTEGER NOT NULL DEFAULT 0);
CREATE TABLE reports (id TEXT PRIMARY KEY, location_id TEXT NOT NULL REFERENCES locations(id) ON DELETE CASCADE, message TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'open', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE support_notes (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, actor_id TEXT NOT NULL, note TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX orders_location_created ON orders(location_id,created_at);
CREATE INDEX audit_tenant ON audit(tenant_id,created_at);
CREATE INDEX memberships_tenant ON memberships(tenant_id);
